import { useState } from 'react';
import './App.css';
import HeaderMenu from './components/Header-Menu';
import LayoutMonitoring from './components/monitoring/Layout-Monitoring';
import LayoutMap from './components/mapview/Layout-Map';
import LayoutMetro from './components/mapview/Layout-Metro';
import AboutProject from './components/AboutProject';

function AppDeviceSolution() {
  const [dataType, setDataType] = useState('Gen');
  const [userId, setUserId] = useState('admin_user');

  // 1. 열려있는 탭 목록과 활성화된 탭 ID 관리
  const [openTabs, setOpenTabs] = useState([{ id: 'Monitoring', label: 'Monitoring' }]);
  const [activeTab, setActiveTab] = useState('Monitoring');

  // 2. 메뉴 클릭 핸들러 (탭 추가 및 전환)
  const handleMenuSelect = (type, label) => {
    // 1. 현재 열린 탭 중 같은 타입이 몇 개인지 확인 (ID 생성용)
    const sameTypeTabs = openTabs.filter((tab) => tab.id.startsWith(type));
    const newInstanceId = sameTypeTabs.length > 0 ? `${type}_${sameTypeTabs.length + 1}` : type;

    // 2. 타이틀도 구분을 위해 "Wafer Map (2)" 식으로 표시하면 좋습니다.
    const newLabel = sameTypeTabs.length > 0 ? `${label} (${sameTypeTabs.length + 1})` : label;

    // 3. 무조건 새 탭으로 추가
    const newTab = { id: newInstanceId, label: newLabel, originalType: type };
    setOpenTabs([...openTabs, newTab]);
    setActiveTab(newInstanceId);
  };

  // 3. 탭 닫기 핸들러
  const closeTab = (e, id) => {
    e.stopPropagation(); // 탭 전환 이벤트 전파 방지
    const newTabs = openTabs.filter((tab) => tab.id !== id);
    setOpenTabs(newTabs);

    // 닫은 탭이 활성 탭이었다면 마지막 남은 탭으로 이동
    if (activeTab === id && newTabs.length > 0) {
      setActiveTab(newTabs[newTabs.length - 1].id);
    }
  };

  return (
    <div className="app-wrapper">
      <HeaderMenu
        className="Top-header"
        onMenuType={(type, label) => handleMenuSelect(type, label)}
        onDataType={setDataType}
      />

      {/* 4. 다이나믹 탭 바 영역 */}
      <div className="tabs-bar">
        {openTabs.map((tab) => (
          <div
            key={tab.id}
            className={`tab-item ${activeTab === tab.id ? 'active' : ''}`}
            onClick={() => setActiveTab(tab.id)}
          >
            <span>{tab.label}</span>
            <button className="close-btn" onClick={(e) => closeTab(e, tab.id)}>
              ×
            </button>
          </div>
        ))}
      </div>

      {/* 5. 컨텐츠 렌더링 영역 */}
      {openTabs.map((tab) => (
        <div
          key={tab.id}
          style={{ display: activeTab === tab.id ? 'block' : 'none', height: '100%' }}
        >
          {/* 탭 ID별로 컴포넌트를 매핑 */}
          {tab.id.startsWith('Monitoring') && <LayoutMonitoring userId={userId} />}
          {tab.id.startsWith('Map') && <LayoutMap dataType={dataType} userId={userId} />}
          {tab.id.startsWith('Metro') && <LayoutMetro dataType={dataType} userId={userId} />}
          {tab.id.startsWith('About') && <AboutProject />}
        </div>
      ))}
    </div>
  );
}

export default AppDeviceSolution;
