// DataGenerator.js

export const generateDatas = (selectedParams) => {
  const newData = [];
  const excludeKeys = ['y2item', 'chartEngine', 'chartType', 'date'];

  // 1. 조합 대상 키 필터링 (계층 구조 관리를 위해 y1item, step 등은 별도 처리 권장되나 일단 포함)
  const targetKeys = Object.keys(selectedParams).filter(
    (key) =>
      !excludeKeys.includes(key) &&
      Array.isArray(selectedParams[key]) &&
      selectedParams[key].length > 0,
  );

  // 모든 조건 조합 생성 (Line, Process, PartID 등)
  const getCombinations = (keys, params) => {
    return keys.reduce(
      (acc, key) => {
        const combinations = [];
        acc.forEach((prevCombination) => {
          params[key].forEach((value) => {
            combinations.push({ ...prevCombination, [key]: value });
          });
        });
        return combinations;
      },
      [{}],
    );
  };

  const allCombinations = getCombinations(targetKeys, selectedParams);

  // 2. 시간 누적을 위한 기준 시점 설정
  let globalStartTime = new Date();
  globalStartTime.setHours(globalStartTime.getHours() - 24); // 24시간 전부터 시작

  const lotCount = 2;
  const waferCount = 5;

  // 3. 데이터 생성 루프
  allCombinations.forEach((combination, combIdx) => {
    // 각 조합(Step/Item 등)별로 고유한 시작 시간을 부여하기 위해 약간의 offset
    let combinationStartTime = new Date(globalStartTime.getTime() + combIdx * 3600000);

    for (let l = 0; l < lotCount; l++) {
      const lotId = `LOT-${String(l + 1).padStart(3, '0')}`;
      // Lot별로 1시간 간격
      let lotStartTime = new Date(combinationStartTime.getTime() + l * 3600000);

      for (let w = 0; w < waferCount; w++) {
        const waferId = `W-${String(w + 1).padStart(2, '0')}`;

        // 웨이퍼당 1분씩 추가 (tkin_time과 tkout_time 사이의 간격 생성)
        // 실제 현장 데이터처럼 각 Wafer마다 미세하게 다른 시간을 부여합니다.
        const waferInMs = lotStartTime.getTime() + w * 60000;
        const waferOutMs = waferInMs + 45000; // 가공 시간 45초 가정

        const baseValue = Math.random() * 80 + 10;

        const row = {
          ...combination,
          lot_id: lotId,
          wafer_id: waferId,
          value: parseFloat((baseValue + Math.random() * 5).toFixed(2)),
          // ISO 문자열을 포맷팅하여 YYYY-MM-DD HH:mm:ss 형식으로 변환
          tkin_time: new Date(waferInMs).toISOString().replace('T', ' ').split('.')[0],
          tkout_time: new Date(waferOutMs).toISOString().replace('T', ' ').split('.')[0],
        };

        newData.push(row);
      }
    }
  });

  return newData;
};
