import React, { useState, useEffect, useRef } from 'react';
import ColorRowList from './ColorRowList';

// 프리셋 색상 정의 (데이터 매핑)
const COLOR_PRESETS = {
  parula: ['#352a87', '#0363e1', '#1485d4', '#06a7c6', '#38b99e', '#92bf73', '#d9ba56', '#f9fb0e'],
  jet: [
    '#00008f',
    '#0000ff',
    '#007fff',
    '#00ffff',
    '#7fff7f',
    '#ffff00',
    '#ff7f00',
    '#ff0000',
    '#7f0000',
  ],
  turbo: [
    '#30123b',
    '#414690',
    '#4674e2',
    '#2f9df5',
    '#1ad4d8',
    '#52f667',
    '#a2fc3c',
    '#e8d831',
    '#fbb31e',
    '#f67d10',
    '#d24b03',
    '#a72202',
    '#7a0403',
  ],
};

const SetupColorModel = ({ isOpen, onClose, onApply, anchorRef }) => {
  const [type, setType] = useState('parula');
  const [step, setStep] = useState(100);
  const [startColor, setStartColor] = useState('#ffffff');
  const [midColor, setMidColor] = useState('#3b82f6');
  const [endColor, setEndColor] = useState('#ef4444');
  const [generatedColors, setGeneratedColors] = useState([]);
  const [pos, setPos] = useState({ top: 0, left: 0 });

  // 버튼 위치 추적
  useEffect(() => {
    if (isOpen && anchorRef?.current) {
      const rect = anchorRef.current.getBoundingClientRect();
      setPos({
        top: rect.bottom + window.scrollY + 8,
        left: rect.left + window.scrollX - 210, // 모달 너비에 맞춰 정렬 조절
      });
    }
  }, [isOpen, anchorRef]);

  // 보간 함수 (RGB)
  const interpolate = (c1, c2, f) => {
    const r1 = parseInt(c1.substring(1, 3), 16),
      g1 = parseInt(c1.substring(3, 5), 16),
      b1 = parseInt(c1.substring(5, 7), 16);
    const r2 = parseInt(c2.substring(1, 3), 16),
      g2 = parseInt(c2.substring(3, 5), 16),
      b2 = parseInt(c2.substring(5, 7), 16);
    const r = Math.round(r1 + f * (r2 - r1)),
      g = Math.round(g1 + f * (g2 - g1)),
      b = Math.round(b1 + f * (b2 - b1));
    return `#${((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1)}`;
  };

  // 색상 생성 로직
  useEffect(() => {
    let result = [];
    const n = Number(step);

    if (COLOR_PRESETS[type]) {
      const preset = COLOR_PRESETS[type];
      for (let i = 0; i < n; i++) {
        const idx = (i / (n - 1)) * (preset.length - 1);
        const low = Math.floor(idx),
          high = Math.ceil(idx);
        result.push(interpolate(preset[low], preset[high], idx - low));
      }
    } else if (type === 'one') {
      for (let i = 0; i < n; i++) result.push(interpolate('#ffffff', endColor, i / (n - 1)));
    } else if (type === 'two') {
      for (let i = 0; i < n; i++) result.push(interpolate(startColor, endColor, i / (n - 1)));
    } else if (type === 'three') {
      const half = Math.floor(n / 2);
      for (let i = 0; i < half; i++) result.push(interpolate(startColor, midColor, i / (half - 1)));
      for (let i = half; i < n; i++)
        result.push(interpolate(midColor, endColor, (i - half) / (n - half - 1)));
    }
    setGeneratedColors(result);
  }, [type, step, startColor, midColor, endColor]);

  if (!isOpen) return null;

  const isPreset = ['parula', 'jet', 'turbo'].includes(type);

  return (
    <div style={modalOverlayStyle} onClick={onClose}>
      <div
        style={{ ...modalContainerStyle, top: pos.top, left: pos.left }}
        onClick={(e) => e.stopPropagation()}
      >
        <div style={titleStyle}>🎨 Color Palette Setup</div>

        <div style={headerSectionStyle}>
          <div style={inputGroupStyle}>
            <label style={labelStyle}>Gradient Type</label>
            <select style={selectStyle} value={type} onChange={(e) => setType(e.target.value)}>
              {['parula', 'jet', 'turbo', 'one', 'two', 'three'].map((t) => (
                <option key={t} value={t}>
                  {t.toUpperCase()}
                </option>
              ))}
            </select>
          </div>
          <div style={inputGroupStyle}>
            <label style={labelStyle}>Steps</label>
            <input
              style={selectStyle}
              type="number"
              value={step}
              onChange={(e) => setStep(e.target.value)}
              min="2"
              max="100"
            />
          </div>

          {!isPreset && (
            <div style={colorPickerGroupStyle}>
              {type !== 'one' && (
                <div style={pickerWrapper}>
                  <label style={labelStyle}>Start</label>
                  <input
                    type="color"
                    style={colorInput}
                    value={startColor}
                    onChange={(e) => setStartColor(e.target.value)}
                  />
                </div>
              )}
              {type === 'three' && (
                <div style={pickerWrapper}>
                  <label style={labelStyle}>Mid</label>
                  <input
                    type="color"
                    style={colorInput}
                    value={midColor}
                    onChange={(e) => setMidColor(e.target.value)}
                  />
                </div>
              )}
              <div style={pickerWrapper}>
                <label style={labelStyle}>End</label>
                <input
                  type="color"
                  style={colorInput}
                  value={endColor}
                  onChange={(e) => setEndColor(e.target.value)}
                />
              </div>
            </div>
          )}
        </div>

        <div style={middleSectionStyle}>
          <div style={{ width: '100%', padding: '0 5px' }}>
            <ColorRowList colors={generatedColors} step={step} />
          </div>
        </div>

        <div style={footerSectionStyle}>
          <button onClick={onClose} style={cancelBtnStyle}>
            Cancel
          </button>
          <button onClick={() => onApply(generatedColors)} style={applyBtnStyle}>
            Apply
          </button>
        </div>
      </div>
    </div>
  );
};

// --- Styles ---
const modalOverlayStyle = {
  position: 'fixed',
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: 'transparent',
  zIndex: 3000,
};
const modalContainerStyle = {
  position: 'absolute',
  backgroundColor: '#fff',
  padding: '20px',
  borderRadius: '12px',
  width: '420px',
  boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1)',
  border: '1px solid #e2e8f0',
  display: 'flex',
  flexDirection: 'column',
  gap: '16px',
};
const titleStyle = {
  fontSize: '15px',
  fontWeight: 'bold',
  color: '#1e293b',
  borderBottom: '1px solid #f1f5f9',
  paddingBottom: '10px',
};
const headerSectionStyle = { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' };
const labelStyle = {
  fontSize: '11px',
  fontWeight: '600',
  color: '#64748b',
  marginBottom: '4px',
  display: 'block',
};
const selectStyle = {
  padding: '6px',
  borderRadius: '6px',
  border: '1px solid #cbd5e1',
  fontSize: '13px',
};
const inputGroupStyle = { display: 'flex', flexDirection: 'column' };
const colorPickerGroupStyle = {
  gridColumn: '1 / span 2',
  display: 'flex',
  gap: '20px',
  padding: '10px',
  backgroundColor: '#f8fafc',
  borderRadius: '8px',
};
const pickerWrapper = {
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  gap: '4px',
};
const colorInput = {
  width: '40px',
  height: '24px',
  border: 'none',
  cursor: 'pointer',
  backgroundColor: 'transparent',
};
const middleSectionStyle = {
  display: 'flex',
  border: '1px solid #f1f5f9',
  borderRadius: '6px',
  overflow: 'hidden',
};
const footerSectionStyle = {
  display: 'flex',
  justifyContent: 'flex-end',
  gap: '8px',
  paddingTop: '10px',
};
const applyBtnStyle = {
  padding: '8px 16px',
  backgroundColor: '#3b82f6',
  color: '#fff',
  border: 'none',
  borderRadius: '6px',
  fontSize: '13px',
  fontWeight: '600',
  cursor: 'pointer',
};
const cancelBtnStyle = {
  padding: '8px 16px',
  backgroundColor: '#f1f5f9',
  color: '#475569',
  border: 'none',
  borderRadius: '6px',
  fontSize: '13px',
  cursor: 'pointer',
};

export default SetupColorModel;
